  static List<String> get categories =>
      conductors.map((c) => c.category).toSet().toList()..sort();

  static List<ConductorEntry> byCategory(String category) =>
      conductors.where((c) => c.category == category).toList();

  static List<ConductorEntry> search(String query) {
    final q = query.toLowerCase();
    return conductors.where((c) =>
      c.code.toLowerCase().contains(q) ||
      c.category.toLowerCase().contains(q)
    ).toList();
  }
